import { useRef } from "react";
import { Button, Popover, useDisclosure } from "../ui/primitives.jsx";
import { Icon } from "../ui/icons.jsx";

const TARGETS = ["Kanal A", "Kanal B", "Kanal C", "E-Mail", "Link kopieren"];

export default function ShareMenu() {
    const anchorRef = useRef(null);
    const { open, toggle, close } = useDisclosure();
    return (
        <>
            <Button ref={anchorRef} variant="round" aria-label="Teilen" aria-expanded={open} onClick={toggle}>
                <Icon name="share" size={18} />
            </Button>
            <Popover anchorRef={anchorRef} open={open} onClose={close} align="end" className="w-56">
                <ul className="flex flex-col gap-1">
                    {TARGETS.map((target) => (
                        <li key={target}><button type="button" className="w-full rounded-sm px-2 py-1.5 text-left text-sm hover:bg-brand-50" onClick={close}>{target}</button></li>
                    ))}
                </ul>
            </Popover>
        </>
    );
}
